parameters.jsCode:
const body = $input.first().json.body;
const required = ['organization_name', 'crisis_description', 'crisis_type', 'audiences'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.crisis_description.trim().length < 50) return [{ json: { valid: false, error: 'crisis_description too short' } }];

const crisisTypes = ['product_outage', 'data_breach', 'pr_scandal', 'safety_incident', 'executive_misconduct', 'financial_issue', 'legal_action', 'service_disruption', 'misinformation', 'natural_disaster', 'employee_incident', 'regulatory_action', 'other'];
const crisisType = crisisTypes.includes(body.crisis_type) ? body.crisis_type : 'other';

const audiences = Array.isArray(body.audiences)
  ? body.audiences
  : (body.audiences || '').split(',').map(a => a.trim()).filter(Boolean);

const urgencies = ['immediate', 'within_hours', 'within_day', 'proactive'];
const urgency = urgencies.includes(body.urgency) ? body.urgency : 'within_hours';

return [{ json: {
  valid: true,
  orgName: body.organization_name.trim(),
  orgType: body.org_type || 'company',
  crisisType,
  urgency,
  crisisDescription: body.crisis_description.trim().slice(0, 2000),
  knownFacts: (body.known_facts || '').slice(0, 800),
  unknownFacts: (body.unknown_facts || '').slice(0, 400),
  actionsTaken: (body.actions_taken || '').slice(0, 600),
  audiences,
  spokesPerson: body.spokesperson || '',
  legalReview: body.legal_review_required !== false,
  tone: body.tone || 'empathetic_professional',
  avoidClaims: (body.avoid_claims || '').slice(0, 300),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Draft crisis communications.

Organization: {{ $json.orgName }} ({{ $json.orgType }})
Crisis type: {{ $json.crisisType.replace(/_/g,' ') }}
Urgency: {{ $json.urgency.replace(/_/g,' ') }}
Spokesperson: {{ $json.spokesPerson || 'not specified' }}
Tone: {{ $json.tone.replace(/_/g,' ') }}
Legal review required: {{ $json.legalReview }}
Audiences to draft for: {{ $json.audiences.join(', ') }}

Crisis description:
{{ $json.crisisDescription }}

Known facts:
{{ $json.knownFacts || 'not provided — draft conservatively' }}

Unknown or unconfirmed facts:
{{ $json.unknownFacts || 'none specified' }}

Actions already taken:
{{ $json.actionsTaken || 'none yet' }}

Claims/statements to avoid:
{{ $json.avoidClaims || 'none specified' }}

Return this JSON:
{
  "situation_assessment": {
    "severity": "one of: minor | moderate | serious | severe | critical",
    "reputation_risk": "one of: low | medium | high | extreme",
    "key_stakeholder_concern": "the primary concern each affected group will have — one sentence per audience"
  },
  "communications_strategy": "2-3 sentences on the overall approach for this specific crisis — what to lead with, what to avoid, what the organization's position should be",
  "statements": {
    "holding_statement": "a short statement (2-4 sentences) to use immediately while facts are being gathered — neutral, acknowledges the situation, commits to update",
    "customer_statement": "full statement for customers or end users — empathetic, specific to their impact, actionable",
    "employee_statement": "full statement for internal employees — more direct, acknowledges their concerns, emphasizes what leadership is doing",
    "media_statement": "press statement — factual, complete, quote from spokesperson if provided",
    "social_media_post": "a single short post (under 280 chars) for Twitter/X — acknowledges the situation, points to more info",
    "faq_responses": [
      {
        "question": "question your audiences will ask",
        "answer": "honest, clear answer — or honest acknowledgment if you don't know yet"
      }
    ]
  },
  "what_not_to_say": ["specific phrases or claims to avoid in all communications — with brief reason why"],
  "timeline_recommendations": [
    {
      "timeframe": "within 1 hour",
      "action": "what to communicate and to whom",
      "channel": "which channel"
    }
  ],
  "legal_review_flags": ["specific statements or claims in these drafts that should be reviewed by legal counsel before publishing"],
  "monitoring_recommendations": ["what to monitor for and how to know if communications are landing well or poorly"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let comms;
try { comms = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
comms._meta = { orgName: input.orgName, crisisType: input.crisisType, urgency: input.urgency, audiences: input.audiences, legalReview: input.legalReview, replyEmail: input.replyEmail };
return [{ json: comms }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const severityConfig = {minor:{color:'#6b7280',bg:'#f9fafb'},moderate:{color:'#2563eb',bg:'#eff6ff'},serious:{color:'#d97706',bg:'#fffbeb'},severe:{color:'#ea580c',bg:'#fff7ed'},critical:{color:'#dc2626',bg:'#fef2f2'}};
const sa = c.situation_assessment || {};
const sc = severityConfig[sa.severity] || severityConfig.moderate;

const urgencyLabel = m.urgency === 'immediate' ? '🚨 IMMEDIATE' : m.urgency === 'within_hours' ? '⚡ Within Hours' : m.urgency === 'within_day' ? '📋 Within 24 Hours' : '📢 Proactive';

const stmts = c.statements || {};
const statementBlocks = [
  {key: 'holding_statement', label: 'Holding Statement', icon: '⏳', color: '#6b7280', desc: 'Use immediately while facts are gathered'},
  {key: 'customer_statement', label: 'Customer Statement', icon: '👥', color: '#2563eb'},
  {key: 'employee_statement', label: 'Employee Statement', icon: '🏢', color: '#7c3aed'},
  {key: 'media_statement', label: 'Press Statement', icon: '📰', color: '#0891b2'},
  {key: 'social_media_post', label: 'Social Media Post', icon: '📱', color: '#16a34a'},
].filter(s => stmts[s.key] && m.audiences.some(a => s.key.includes('holding') || s.key.includes(a.toLowerCase().replace(/\s/g,'_')) || m.audiences.includes('all')))
 .map(s => `<div style="border-left:4px solid ${s.color};padding:14px 18px;background:#fafafa;border-radius:0 6px 6px 0;margin-bottom:14px">
    <div style="font-size:12px;font-weight:700;color:${s.color};margin-bottom:4px;text-transform:uppercase;letter-spacing:0.4px">${s.icon} ${esc(s.label)}${s.desc ? ' <span style="font-weight:400;color:#9ca3af;text-transform:none">— ' + esc(s.desc) + '</span>' : ''}</div>
    <div style="font-size:14px;line-height:1.8;white-space:pre-wrap;color:#1a1a1a">${esc(stmts[s.key])}</div>
  </div>`).join('');

const allStatements = [
  {key: 'holding_statement', label: '⏳ Holding Statement', color: '#6b7280'},
  {key: 'customer_statement', label: '👥 Customer Statement', color: '#2563eb'},
  {key: 'employee_statement', label: '🏢 Employee Statement', color: '#7c3aed'},
  {key: 'media_statement', label: '📰 Press Statement', color: '#0891b2'},
  {key: 'social_media_post', label: '📱 Social Media', color: '#16a34a'},
].filter(s => stmts[s.key])
 .map(s => `<div style="border-left:4px solid ${s.color};padding:14px 18px;background:#fafafa;border-radius:0 6px 6px 0;margin-bottom:14px">
    <div style="font-size:12px;font-weight:700;color:${s.color};margin-bottom:6px;text-transform:uppercase">${esc(s.label)}</div>
    <div style="font-size:14px;line-height:1.8;white-space:pre-wrap;color:#1a1a1a">${esc(stmts[s.key])}</div>
  </div>`).join('');

const faqBlocks = (stmts.faq_responses||[]).map(faq => `<div style="margin-bottom:12px"><div style="font-size:14px;font-weight:600;color:#1a1a1a;margin-bottom:4px">Q: ${esc(faq.question)}</div><div style="font-size:14px;color:#374151;line-height:1.65;background:#f9fafb;padding:8px 12px;border-radius:4px">A: ${esc(faq.answer)}</div></div>`).join('');

const timeline = (c.timeline_recommendations||[]).map(t => `<div style="display:flex;gap:12px;padding:9px 0;border-bottom:1px solid #f3f4f6;align-items:flex-start"><span style="font-size:12px;font-weight:700;color:#dc2626;white-space:nowrap;min-width:100px">${esc(t.timeframe)}</span><div><div style="font-size:14px;color:#374151">${esc(t.action)}</div><div style="font-size:12px;color:#9ca3af">${esc(t.channel||'')}</div></div></div>`).join('');

const avoidList = (c.what_not_to_say||[]).map(w => `<div style="font-size:13px;color:#7f1d1d;padding:4px 0">✗ ${esc(w)}</div>`).join('');
const legalFlags = (c.legal_review_flags||[]).map(f => `<li style="font-size:13px;color:#7f1d1d;margin-bottom:5px">${esc(f)}</li>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1a1a1a;color:#fff;padding:18px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:4px">Crisis Communications · ${urgencyLabel}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.orgName)} — ${esc(m.crisisType.replace(/_/g,' '))}</div>
  </div>
  <div style="background:${sc.bg};padding:12px 28px;border:1px solid ${sc.color}44;border-top:none;display:flex;gap:12px;align-items:center;flex-wrap:wrap">
    <span style="background:${sc.color};color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:10px">SEVERITY: ${esc((sa.severity||'?').toUpperCase())}</span>
    <span style="background:${sa.reputation_risk==='extreme'?'#dc2626':sa.reputation_risk==='high'?'#d97706':'#6b7280'};color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:10px">REPUTATION RISK: ${esc((sa.reputation_risk||'?').toUpperCase())}</span>
    ${m.legalReview ? '<span style="background:#7c3aed;color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:10px">LEGAL REVIEW REQUIRED</span>' : ''}
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Communications strategy</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0">${esc(c.communications_strategy)}</p>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:12px">Draft statements</div>
    ${allStatements}
  </div>
  ${faqBlocks ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">FAQ responses</div>
    ${faqBlocks}
  </div>` : ''}
  ${timeline ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Response timeline</div>
    ${timeline}
  </div>` : ''}
  ${avoidList ? `<div style="background:#fef2f2;padding:14px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:7px">Do NOT say</div>
    ${avoidList}
  </div>` : ''}
  ${legalFlags ? `<div style="background:#f5f3ff;padding:14px 28px;border:1px solid #ddd6fe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#7c3aed;margin-bottom:7px">Flag for legal review before publishing</div>
    <ul style="padding-left:18px;margin:0">${legalFlags}</ul>
  </div>` : ''}
  <div style="background:#1a1a1a;color:#4b5563;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Crisis Comms Drafter · ${esc(m.orgName)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, orgName: m.orgName, crisisType: m.crisisType, severity: sa.severity, comms: c } }];
